import pytest

from midi2mkcd import InvalidSongError
from midi2mkcd.utils.song_text import parse_song_text


def test_plain_hex_literal() -> None:
    song = parse_song_text("hex`00 78\n00`")
    assert song.hex == "007800"
    assert not song.is_code_extra
    assert song.track_instrument_map == []


def test_code_extra_constants() -> None:
    text = (
        "// Generated by someone\n"
        "const songHex = hex`0078`;\n"
        "const midiDrumNoteMap: number[] = [36, 38];\n"
        "const trackInstrumentMap: number[] = [0, -1];\n"
        "const lyricTicks: number[] = [0, 24];\n"
        'const lyricTexts: string[] = ["caf\\u00e9 ", "a \\"b\\"; c]", "日本"];\n'
    )
    song = parse_song_text(text)
    assert song.is_code_extra
    assert song.hex == "0078"
    assert song.midi_drum_note_map == [36, 38]
    assert song.track_instrument_map == [0, -1]
    assert song.lyric_ticks == [0, 24]
    assert song.lyric_texts == ["café ", 'a "b"; c]', "日本"]


@pytest.mark.parametrize(
    ("text", "message"),
    [
        ("no song here", "found none"),
        ("hex`00` hex`01`", "found 2"),
        ("hex``", "isn't a valid hex"),
        ("hex`0`", "isn't a valid hex"),
        ("hex`zz`", "isn't a valid hex"),
        (
            "const songHex = hex`00`;\nconst trackInstrumentMap: number[] = [0,;\n",
            "Could not parse trackInstrumentMap",
        ),
        (
            'const songHex = hex`00`;\nconst trackInstrumentMap: number[] = ["0"];\n',
            "only hold integers",
        ),
    ],
)
def test_bad_text_is_rejected(text: str, message: str) -> None:
    with pytest.raises(InvalidSongError, match=message):
        parse_song_text(text)
